function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must be lists of the same length.';
  if (operations[0] !== 'FileSystem' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with FileSystem and no arguments.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to createPath and get.';
  const isPath = path => typeof path === 'string' && path.length >= 2 && path.length <= 100 && /^(\/[a-z]+)+$/.test(path);
  for (let i = 1; i < operations.length; i++) {
    const call = args[i];
    if (operations[i] === 'createPath') {
      if (!Array.isArray(call) || call.length !== 2 || !isPath(call[0])) return 'createPath needs a valid path of 2 to 100 characters, like "/a/b".';
      if (!Number.isInteger(call[1]) || call[1] < 1 || call[1] > 1e9) return 'value is an integer from 1 to 10^9.';
    } else if (operations[i] === 'get') {
      if (!Array.isArray(call) || call.length !== 1 || !isPath(call[0])) return 'get needs a valid path of 2 to 100 characters, like "/a/b".';
    } else return 'Only createPath and get can follow the constructor.';
  }
  return null;
}

