class FileSystem {
  // A trie: each node maps a part name to a child node.
  constructor() {
    this.root = { children: new Map(), value: -1 };
  }
  createPath(path, value) {
    const parts = path.split('/').slice(1);
    let node = this.root;
    for (let k = 0; k < parts.length - 1; k++) {
      node = node.children.get(parts[k]);
      if (!node) return false;
    }
    const last = parts[parts.length - 1];
    if (node.children.has(last)) return false;
    node.children.set(last, { children: new Map(), value });
    return true;
  }
  get(path) {
    let node = this.root;
    for (const part of path.split('/').slice(1)) {
      node = node.children.get(part);
      if (!node) return -1;
    }
    return node.value;
  }
}

