function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const words = size === 'large'
    ? ['leet', 'code', 'a', 'b', 'docs', 'src', 'lib', 'x', 'y', 'z', 'data', 'tmp', 'home', 'constructor', 'zzzzzzzzzzzzzzzzzzzz']
    : ['a', 'b', 'c'];
  const maxDepth = size === 'large' ? 6 : 3;
  const randomPath = () => {
    let path = '';
    const depth = 1 + pick(maxDepth);
    for (let d = 0; d < depth; d++) path += '/' + words[pick(words.length)];
    return path.length <= 100 ? path : path.slice(0, path.lastIndexOf('/', 100));
  };
  const created = [];
  const operations = ['FileSystem'];
  const args = [[]];
  const calls = size === 'large' ? 499 : 1 + pick(8);
  for (let c = 0; c < calls; c++) {
    const roll = rand();
    let path;
    if (created.length && roll < 0.45) {
      // A child of a stored path, which usually succeeds.
      path = created[pick(created.length)] + '/' + words[pick(words.length)];
      if (path.length > 100) path = randomPath();
    } else if (created.length && roll < 0.6) {
      path = created[pick(created.length)];
    } else {
      path = randomPath();
    }
    if (rand() < 0.55) {
      const value = 1 + pick(size === 'large' ? 1e9 : 20);
      operations.push('createPath');
      args.push([path, value]);
      const parent = path.slice(0, path.lastIndexOf('/'));
      if (!created.includes(path) && (parent === '' || created.includes(parent))) created.push(path);
    } else {
      operations.push('get');
      args.push([path]);
    }
  }
  return [operations, args];
}
